_out += "\r\n<!DOCTYPE html>\r\n<html lang=\"id\">\r\n<head>\r\n  <meta charset=\"UTF-8\">\r\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\r\n  <title>Koreksi KM</title>\r\n  <style>\r\n  * { box-sizing: border-box; margin: 0; padding: 0; }\r\n  body { font-family:-apple-system, BlinkMacSystemFont, \"Segoe UI\", Roboto, Arial, sans-serif;\r\n         background:#f5f5f5; min-height:100vh; color:#1f2937; }\r\n\r\n  .navbar { background:#fff; padding:1rem 2rem; border-bottom:2px solid #e5e7eb;\r\n            box-shadow:0 1px 3px rgba(0,0,0,.1); margin-bottom:1.5rem; }\r\n  .nav-brand { font-weight:700; font-size:1.25rem; display:flex; align-items:center;\r\n               gap:.5rem; margin-bottom:1rem; }\r\n  .nav-menu { display:flex; gap:.5rem; flex-wrap:wrap; }\r\n  .nav-link { padding:.625rem 1.25rem; color:#6b7280; text-decoration:none;\r\n              border-radius:8px; font-weight:500; }\r\n  .nav-link:hover { background:#f3f4f6; color:#1f2937; }\r\n  .nav-link.active { background:#fef3c7; color:#b45309; font-weight:600; }\r\n\r\n  .container { max-width:1000px; margin:0 auto; padding:0 2rem 3rem; }\r\n  h1 { font-size:1.85rem; font-weight:700; }\r\n  .sub { color:#6b7280; margin:.35rem 0 1.4rem; max-width:70ch; line-height:1.6; }\r\n\r\n  .kartu { background:#fff; border:1px solid #e5e7eb; border-radius:13px;\r\n           padding:1.1rem 1.25rem; margin-bottom:1rem; }\r\n  .kartu-judul { font-size:.78rem; text-transform:uppercase; letter-spacing:.4px;\r\n                 color:#6b7280; font-weight:700; margin-bottom:.5rem; }\r\n\r\n  label { display:block; font-size:.82rem; font-weight:600; color:#374151; margin-bottom:.3rem; }\r\n  select, input[type=number], input[type=text], textarea {\r\n    width:100%; padding:.6rem .75rem; border:2px solid #e5e7eb; border-radius:8px;\r\n    font-size:.92rem; font-family:inherit; background:#fff; color:#1f2937; }\r\n  select:focus, input:focus, textarea:focus { outline:none; border-color:#b45309; }\r\n  .baris { display:grid; grid-template-columns:repeat(auto-fit,minmax(190px,1fr)); gap:.8rem; }\r\n\r\n  .btn { padding:.6rem 1.1rem; border:none; border-radius:8px; font-weight:700;\r\n         font-size:.87rem; cursor:pointer; font-family:inherit; }\r\n  .btn-utama { background:#b45309; color:#fff; }\r\n  .btn-utama:disabled { background:#d6d3d1; cursor:not-allowed; }\r\n  .btn-halus { background:#fff; color:#6b7280; border:1px solid #e5e7eb; }\r\n\r\n  .scroll { overflow-x:auto; }\r\n  table { width:100%; border-collapse:collapse; font-size:.84rem; min-width:640px; }\r\n  th { background:#f9fafb; border-bottom:2px solid #e5e7eb; padding:.5rem .6rem;\r\n       text-align:left; font-size:.68rem; text-transform:uppercase; letter-spacing:.3px;\r\n       color:#6b7280; font-weight:700; white-space:nowrap; }\r\n  td { border-bottom:1px solid #f1f5f9; padding:.5rem .6rem; color:#334155;\r\n       font-variant-numeric:tabular-nums; }\r\n  .num { text-align:right; }\r\n  .kosong { color:#a0aec0; font-style:italic; }\r\n\r\n  /* Dua bentuk kejanggalan, dua warna — karena akibatnya berbeda jauh. */\r\n  tr.mundur td { background:#fffbeb; }\r\n  tr.melompat td { background:#fef2f2; }\r\n  .tag { display:inline-block; font-size:.66rem; font-weight:800; padding:1px 6px;\r\n         border-radius:4px; text-transform:uppercase; letter-spacing:.3px; }\r\n  .tag-mundur { background:#fde68a; color:#78350f; }\r\n  .tag-melompat { background:#fecaca; color:#7f1d1d; }\r\n\r\n  .acuan { background:#f0f9ff; border:1px solid #bae6fd; color:#075985;\r\n           border-radius:9px; padding:.7rem .9rem; font-size:.85rem; line-height:1.55; }\r\n  .catatan { background:#fffbeb; border:1px solid #fde68a; color:#78350f;\r\n             border-radius:9px; padding:.75rem .9rem; font-size:.8rem; line-height:1.55; }\r\n  .hampa { text-align:center; padding:2.2rem 1rem; color:#94a3b8; }\r\n  @media (max-width:640px) { .navbar,.container { padding-left:1rem; padding-right:1rem; } }\r\n  </style>\r\n  <style id=\"ds-theme\">\n:root{\n  --bg:#F8FAFC;--bg-secondary:#F3F4F6;--card:#FFFFFF;--border:#E5E7EB;--divider:#E5E7EB;\n  --text:#111827;--text-secondary:#6B7280;--text-disabled:#9CA3AF;\n  --primary:#4F633F;--primary-hover:#384B2B;--primary-active:#223215;--primary-soft:#F1F4EE;--primary-soft-border:#D2E9BB;\n  --tertiary-10:#0B1407;--tertiary-20:#223215;--tertiary-30:#384B2B;--tertiary-40:#4F633F;--tertiary-50:#687D56;--tertiary-60:#81956F;--tertiary-70:#9BB288;--tertiary-80:#B6CDA1;--tertiary-90:#D2E9BB;--tertiary-95:#DEF7C7;--tertiary-98:#EEFEDA;\n  --success:#10B981;--warning:#F59E0B;--error:#EF4444;--info:#0EA5E9;\n  --radius:16px;--radius-sm:10px;--input-border:#D1D5DB;\n  --shadow:0 4px 12px rgba(0,0,0,.05);--shadow-hover:0 8px 24px rgba(0,0,0,.08);\n  --focus-ring:0 0 0 3px rgba(79,99,63,.25);\n}\nbody{background:var(--bg)!important;color:var(--text)!important;}\na{color:var(--primary);}\n.navbar{background:var(--card)!important;border-bottom:1px solid var(--border)!important;box-shadow:0 1px 2px rgba(0,0,0,.04)!important;}\n.nav-brand{color:var(--text)!important;}\n.nav-link{color:var(--text-secondary)!important;border-radius:var(--radius-sm)!important;}\n.nav-link:hover{background:var(--bg-secondary)!important;color:var(--text)!important;}\n.nav-link.active{background:var(--primary-soft)!important;color:var(--primary)!important;box-shadow:inset 0 -2px 0 var(--primary)!important;border-color:var(--primary)!important;}\n.user-email{color:var(--text-secondary)!important;}\n.btn-primary,.btn-create,.btn-edit,.btn-save,.btn-download,.btn-submit,.btn-export,.btn-approve,.btn-utama{\n  background:var(--primary)!important;color:#fff!important;border:1px solid var(--primary)!important;border-radius:var(--radius-sm)!important;}\n.btn-primary:hover,.btn-create:hover,.btn-edit:hover,.btn-save:hover,.btn-download:hover,.btn-submit:hover,.btn-export:hover,.btn-approve:hover,.btn-utama:hover{\n  background:var(--primary-hover)!important;border-color:var(--primary-hover)!important;}\n.btn-secondary,.btn-cancel,.btn-back,.btn-back-to-self{\n  background:var(--card)!important;color:var(--text)!important;border:1px solid var(--border)!important;border-radius:var(--radius-sm)!important;}\n.btn-secondary:hover,.btn-cancel:hover,.btn-back:hover,.btn-back-to-self:hover{background:var(--bg-secondary)!important;}\n.btn-danger,.btn-reject{background:var(--error)!important;color:#fff!important;border:1px solid var(--error)!important;border-radius:var(--radius-sm)!important;}\n.btn-danger:hover,.btn-reject:hover{background:#DC2626!important;}\n.btn-success{background:var(--success)!important;color:#fff!important;border:1px solid var(--success)!important;border-radius:var(--radius-sm)!important;}\n.card,.stat-card,.form-container,.wo-card{background:var(--card)!important;border:1px solid var(--border)!important;border-radius:var(--radius)!important;box-shadow:var(--shadow)!important;}\n.card:hover,.stat-card:hover,.wo-card:hover{box-shadow:var(--shadow-hover)!important;}\n</style>\r\n<script id=\"abadi-gas-shim\">\n(function() {\n  if (window.google && window.google.script && window.google.script.run) return;\n  function getQueryToken() {\n    try {\n      var p = new URLSearchParams(window.location.search);\n      return p.get('token') || '';\n    } catch (_) { return ''; }\n  }\n  function createRunner(successHandler, failureHandler, userObj) {\n    return new Proxy({}, {\n      get: function(target, prop) {\n        if (prop === 'withSuccessHandler') {\n          return function(fn) { return createRunner(fn, failureHandler, userObj); };\n        }\n        if (prop === 'withFailureHandler') {\n          return function(fn) { return createRunner(successHandler, fn, userObj); };\n        }\n        if (prop === 'withUserObject') {\n          return function(obj) { return createRunner(successHandler, failureHandler, obj); };\n        }\n        return function() {\n          var args = Array.prototype.slice.call(arguments);\n          var tok = window.__PAGE_TOKEN__ || (typeof PAGE_TOKEN !== 'undefined' ? PAGE_TOKEN : '') || getQueryToken();\n          var payload = {\n            token: tok,\n            action: prop,\n            data: args[0] !== undefined ? args[0] : null,\n            args: args\n          };\n          fetch('/api/web', {\n            method: 'POST',\n            headers: { 'Content-Type': 'application/json' },\n            body: JSON.stringify(payload)\n          })\n          .then(function(res) {\n            return res.text().then(function(text) {\n              var json = null;\n              try { json = JSON.parse(text); } catch(_) {}\n              if (!res.ok) {\n                var errMsg = (json && json.error && (json.error.message || json.error)) || ('HTTP ' + res.status + ': ' + text);\n                var err = new Error(errMsg);\n                if (failureHandler) failureHandler(err, userObj);\n                else alert('Galat server: ' + errMsg);\n                return;\n              }\n              if (json) {\n                if (successHandler) successHandler(json, userObj);\n              } else {\n                if (successHandler) successHandler(text, userObj);\n              }\n            });\n          })\n          .catch(function(err) {\n            if (failureHandler) failureHandler(err, userObj);\n            else alert('Sambungan terputus: ' + (err.message || err));\n          });\n        };\n      }\n    });\n  }\n  window.google = { script: { run: createRunner(null, null, null) } };\n  // Event delegation untuk menjaga ?token= pada semua navigasi internal /web\n  document.addEventListener('click', function(e) {\n    var a = e.target && e.target.closest('a');\n    if (a && a.href && a.origin === window.location.origin && a.pathname.startsWith('/web')) {\n      var u = new URL(a.href);\n      var tok = window.__PAGE_TOKEN__ || (typeof PAGE_TOKEN !== 'undefined' ? PAGE_TOKEN : '') || getQueryToken();\n      if (tok && !u.searchParams.has('token')) {\n        u.searchParams.set('token', tok);\n        a.href = u.toString();\n      }\n    }\n  }, true);\n})();\n</script>\n</head>\r\n<body>\r\n  <nav class=\"navbar\">\r\n    <div class=\"nav-brand\"><span style=\"font-size:1.5rem;\">⚙️</span> Mechanic Activity Report</div>\r\n    <!-- Tautan menu memakai variabel template baseUrl, BUKAN URL /exec yang\r\n         ditulis harfiah. Router mengisinya dari getScriptUrl(), jadi menu selalu\r\n         menunjuk deployment yang sedang berjalan — sistem ini sendiri.\r\n\r\n         JANGAN menempel URL /exec di sini. Sistem ini lahir sebagai salinan\r\n         KMB V2, dan salinan itu datang membawa 72 tautan ke web app KMB V2.\r\n         URL yang ditempel akan ikut tersalin lagi ke tenant berikutnya —\r\n         persis cara masalah itu lahir. Lihat PANDUAN.html §7.\r\n\r\n         Konsekuensi yang diterima: kalau halaman dibuka lewat /dev, menu ikut\r\n         menjadi /dev, dan /dev menuntut login Google alih-alih menerima token.\r\n         Pemakai biasa memakai /exec, jadi ini hanya menyentuh yang membuka\r\n         /dev dengan sengaja. -->\r\n    <div class=\"nav-menu\">\r\n      ";
