_out += "\r\n    </div>\r\n  </nav>\r\n\r\n  <div class=\"container\">\r\n    <h1>Koreksi KM</h1>\r\n    <p class=\"sub\">\r\n      Jam mesin tidak pernah mundur, jadi angka yang mundur ditolak saat WO dibuat.\r\n      Halaman ini untuk dua hal yang <em>tidak</em> tertangkap pagar itu: angka yang\r\n      salah ketik ke atas — yang justru lolos karena lebih besar — dan panel kilometer yang\r\n      benar-benar diganti.\r\n    </p>\r\n\r\n    <div class=\"kartu\">\r\n      <label for=\"selUnit\">Pilih unit</label>\r\n      <select id=\"selUnit\" onchange=\"muat()\">\r\n        <option value=\"\">— pilih no lambung —</option>\r\n        ";
 for (var i = 0; i < units.length; i++) { var u = units[i];
             if (!u.unit_id || u.unit_id === 'OTHERS' || u.unit_id === 'WORKSHOP') continue; 
_out += "\r\n        <option value=\"";
_out += _esc(u.unit_id);
_out += "\">";
_out += _esc((u.unit_name || u.unit_id));
_out += " (";
_out += _esc(u.unit_id);
_out += ")</option>\r\n        ";
 } 
_out += "\r\n      </select>\r\n    </div>\r\n\r\n    <div id=\"isi\"></div>\r\n  </div>\r\n\r\n  <script>\r\n    var PAGE_TOKEN = '";
_out += _esc(token);
_out += "';\r\n    var DATA = null;\r\n    /* ── TOKEN DITEMPELKAN ULANG SAAT HALAMAN DIMUAT ────────────────────\r\n       Tautan menu sudah membawa token dari server, tapi itu bergantung pada\r\n       token yang terbaca SAAT RENDER. Kalau sekali saja kosong, tautannya\r\n       lahir tanpa token dan tak ada yang membetulkannya - pemakainya lalu\r\n       dilempar ke layar \"perlu token\" tiap berpindah menu.\r\n\r\n       Bedanya dengan fixer di halaman lama: yang ini hanya MENAMBAHKAN token,\r\n       tidak membangun ulang URL dari getScriptUrl(). Alamat /exec tetap yang\r\n       tertulis di tautannya, jadi tak ada kemungkinan tersasar ke deployment\r\n       lain. */\r\n    (function tempelToken() {\r\n      if (!PAGE_TOKEN) return;\r\n      function pasang() {\r\n        var a = document.querySelectorAll('a[href*=\"/macros/s/\"]');\r\n        for (var i = 0; i < a.length; i++) {\r\n          var h = a[i].getAttribute('href') || '';\r\n          if (/token(=|%3d)/i.test(h)) continue;   /* %3d = '=' yang sudah ter-encode */\r\n          a[i].setAttribute('href', h + (h.indexOf('?') !== -1 ? '&' : '?') +\r\n                            'token=' + encodeURIComponent(PAGE_TOKEN));\r\n        }\r\n      }\r\n      if (document.readyState === 'loading') {\r\n        document.addEventListener('DOMContentLoaded', pasang);\r\n      } else { pasang(); }\r\n    })();\r\n\r\n\r\n    function esc(s) {\r\n      return String(s === null || s === undefined ? '' : s)\r\n        .replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/\"/g,'&quot;');\r\n    }\r\n    var BLN = ['Jan','Feb','Mar','Apr','Mei','Jun','Jul','Agt','Sep','Okt','Nov','Des'];\r\n    function jam(v) {\r\n      if (!v) return '<span class=\"kosong\">–</span>';\r\n      var d = new Date(v);\r\n      if (isNaN(d.getTime())) return esc(v);\r\n      function dua(n) { return (n < 10 ? '0' : '') + n; }\r\n      return d.getDate() + ' ' + BLN[d.getMonth()] + ' ' + d.getFullYear() +\r\n             ' <span style=\"color:#94a3b8;\">' + dua(d.getHours()) + ':' + dua(d.getMinutes()) + '</span>';\r\n    }\r\n\r\n    function muat() {\r\n      var u = document.getElementById('selUnit').value;\r\n      var w = document.getElementById('isi');\r\n      if (!u) { w.innerHTML = ''; return; }\r\n      w.innerHTML = '<div class=\"hampa\">Memuat riwayat…</div>';\r\n      google.script.run\r\n        .withSuccessHandler(function(r) {\r\n          if (!r || !r.success) {\r\n            w.innerHTML = '<div class=\"hampa\">' + esc(r && r.error ? r.error.message : 'Gagal memuat') + '</div>';\r\n            return;\r\n          }\r\n          DATA = r.data; gambar();\r\n        })\r\n        .withFailureHandler(function(e) { w.innerHTML = '<div class=\"hampa\">' + esc(e.message) + '</div>'; })\r\n        .handleRiwayatKmUnit({token: PAGE_TOKEN, unit_id: u});\r\n    }\r\n\r\n    function gambar() {\r\n      var d = DATA, h = '';\r\n\r\n      h += '<div class=\"kartu\"><div class=\"kartu-judul\">Acuan sekarang</div>';\r\n      if (d.acuan) {\r\n        h += '<div class=\"acuan\"><b>' + esc(d.acuan.nilai) + '</b> — tercatat ' + jam(d.acuan.at) +\r\n             (d.acuan.oleh ? ' oleh ' + esc(d.acuan.oleh) : '') +\r\n             (d.acuan.wo_number ? ' &middot; ' + esc(d.acuan.wo_number) : '') +\r\n             '<br><span style=\"font-size:.8rem;\">WO berikutnya pada unit ini harus ber-KM ' +\r\n             'sama atau lebih besar daripada angka ini.</span></div>';\r\n      } else {\r\n        h += '<div class=\"acuan\">Belum ada bacaan KM untuk unit ini. Angka pertama yang ' +\r\n             'masuk akan jadi acuannya.</div>';\r\n      }\r\n      h += '</div>';\r\n\r\n      // Ganti panel\r\n      h += '<div class=\"kartu\"><div class=\"kartu-judul\">Panel jam diganti</div>' +\r\n        '<p style=\"font-size:.85rem;color:#6b7280;margin-bottom:.8rem;line-height:1.55;\">' +\r\n        'Sesudah dicatat, hitungan dimulai lagi dari angka baru — bacaan panel lama tidak ' +\r\n        'lagi jadi acuan, dan jam kerja tidak dihitung menyeberangi titik ini.</p>' +\r\n        '<div class=\"baris\">' +\r\n        '<div><label>KM panel baru</label><input type=\"number\" step=\"any\" min=\"0\" id=\"gpKm\" placeholder=\"cth: 0\"></div>' +\r\n        '<div><label>Berlaku sejak</label><input type=\"text\" id=\"gpAt\" placeholder=\"2026-09-01 08:00\"></div>' +\r\n        '</div><div style=\"margin-top:.7rem;\"><label>Alasan</label>' +\r\n        '<textarea id=\"gpAlasan\" rows=\"2\" placeholder=\"cth: panel kilometer rusak, diganti unit baru 1 Sep\"></textarea></div>' +\r\n        '<div style=\"margin-top:.8rem;\"><button class=\"btn btn-utama\" onclick=\"simpanPanel()\">Catat penggantian</button></div>';\r\n      if (d.panel && d.panel.length) {\r\n        h += '<div style=\"margin-top:.9rem;font-size:.82rem;color:#6b7280;\">Sudah tercatat: ';\r\n        for (var p = 0; p < d.panel.length; p++) {\r\n          h += (p ? ' &middot; ' : '') + '<b>' + esc(d.panel[p].nilai) + '</b> sejak ' + jam(d.panel[p].at);\r\n        }\r\n        h += '</div>';\r\n      }\r\n      h += '</div>';\r\n\r\n      // Riwayat bacaan\r\n      h += '<div class=\"kartu\"><div class=\"kartu-judul\">Riwayat bacaan KM</div>';\r\n      if (!d.bacaan.length) {\r\n        h += '<div class=\"hampa\">Belum ada bacaan KM untuk unit ini.</div></div>';\r\n        document.getElementById('isi').innerHTML = h;\r\n        return;\r\n      }\r\n      h += '<div class=\"catatan\"><b>Yang bertanda MELOMPAT paling perlu diperiksa.</b> ' +\r\n        'Angka yang kelewat besar lolos pagar justru karena ia lebih besar — lalu ia jadi acuan, ' +\r\n        'dan setiap bacaan sah sesudahnya ikut tertolak. Satu salah pencet bisa meracuni seluruh ' +\r\n        'riwayat unit ini.</div>';\r\n      h += '<div class=\"scroll\"><table><thead><tr><th>WO</th><th>Tanggal</th><th>Section</th>' +\r\n        '<th>Oleh</th><th class=\"num\">KM</th><th></th><th style=\"width:1%;\"></th></tr></thead><tbody>';\r\n      for (var i = 0; i < d.bacaan.length; i++) {\r\n        var b = d.bacaan[i];\r\n        h += '<tr class=\"' + esc(b.janggal) + '\">' +\r\n          '<td>' + esc(b.wo_number) + '</td>' +\r\n          '<td>' + jam(b.at) + '</td>' +\r\n          '<td>' + esc(b.section || '–') + '</td>' +\r\n          '<td>' + esc(b.oleh_nama || '–') + '</td>' +\r\n          '<td class=\"num\"><b>' + esc(b.nilai) + '</b></td>' +\r\n          '<td>' + (b.janggal ? '<span class=\"tag tag-' + b.janggal + '\">' + b.janggal + '</span>' : '') + '</td>' +\r\n          '<td><button class=\"btn btn-halus\" onclick=\"perbaiki(\\'' + esc(b.wo_id) + '\\',\\'' +\r\n              esc(b.wo_number) + '\\',' + b.nilai + ')\">Perbaiki</button></td></tr>';\r\n      }\r\n      h += '</tbody></table></div></div>';\r\n\r\n      document.getElementById('isi').innerHTML = h;\r\n    }\r\n\r\n    function perbaiki(woId, woNo, kmLama) {\r\n      var baru = prompt('KM baru untuk ' + woNo + '\\n\\nSekarang: ' + kmLama +\r\n        '\\n\\nKosongkan sama sekali kalau angka yang benar tidak diketahui — lebih baik hilang ' +\r\n        'daripada salah.', kmLama);\r\n      if (baru === null) return;\r\n      baru = String(baru).replace(/^\\s+|\\s+$/g, '');\r\n      var alasan = prompt('Alasan koreksi (wajib, minimal 5 huruf).\\n\\n' +\r\n        'Angka KM yang berubah tanpa sebab tertulis mustahil dijelaskan nanti.');\r\n      if (alasan === null) return;\r\n      google.script.run\r\n        .withSuccessHandler(function(r) {\r\n          if (r && r.success) { alert('Tersimpan.'); muat(); }\r\n          else alert('Gagal: ' + (r && r.error ? r.error.message : '?'));\r\n        })\r\n        .withFailureHandler(function(e) { alert('Sambungan terputus: ' + e.message); })\r\n        .handleKoreksiKmWo({token: PAGE_TOKEN, wo_id: woId, km_baru: baru, alasan: alasan});\r\n    }\r\n\r\n    function simpanPanel() {\r\n      var u = document.getElementById('selUnit').value;\r\n      var km = document.getElementById('gpKm').value;\r\n      var at = document.getElementById('gpAt').value;\r\n      var al = document.getElementById('gpAlasan').value;\r\n      if (!u || km === '' || !at || !al) { alert('Unit, KM baru, tanggal berlaku, dan alasan wajib diisi.'); return; }\r\n      google.script.run\r\n        .withSuccessHandler(function(r) {\r\n          if (r && r.success) { alert('Penggantian panel tercatat.'); muat(); }\r\n          else alert('Gagal: ' + (r && r.error ? r.error.message : '?'));\r\n        })\r\n        .withFailureHandler(function(e) { alert('Sambungan terputus: ' + e.message); })\r\n        .handleGantiPanelKm({token: PAGE_TOKEN, unit_id: u, km_baru: km, berlaku_at: at, alasan: al});\r\n    }\r\n  </script>\r\n</body>\r\n</html>\r\n";
return _out;

