_out += "\n    </div>\n    <div id=\"mechSearchEmpty\" class=\"selector-empty\" style=\"display:none;\">Tidak ditemukan mekanik dengan nama tersebut.</div>\n\n    <script>\n      // Kotak teks berisi TOKEN (yang dibagikan ke mekanik); URL penuh disimpan\n      // di data-link dan hanya dipakai tombol \"Buka →\".\n      function _tokenOf(btn) { return btn.parentNode.querySelector('.mon-link').value; }\n      function _linkOf(btn) {\n        var el = btn.parentNode.querySelector('.mon-link');\n        return el.getAttribute('data-link') || el.value;\n      }\n      function _flash(btn) { var o = btn.textContent; btn.textContent = '✅ Tersalin'; setTimeout(function(){ btn.textContent = o; }, 1500); }\n      function _fallbackCopy(link, btn) {\n        var ta = document.createElement('textarea'); ta.value = link; ta.style.position = 'fixed'; ta.style.opacity = '0';\n        document.body.appendChild(ta); ta.select();\n        try { document.execCommand('copy'); _flash(btn); } catch (e) {} document.body.removeChild(ta);\n      }\n      /** Salin TOKEN mekanik (dipakai untuk login di layar awal web & PWA). */\n      function copyToken(btn) {\n        var tok = _tokenOf(btn);\n        if (navigator.clipboard && navigator.clipboard.writeText) {\n          navigator.clipboard.writeText(tok).then(function(){ _flash(btn); }).catch(function(){ _fallbackCopy(tok, btn); });\n        } else { _fallbackCopy(tok, btn); }\n      }\n      /** Disimpan untuk kompatibilitas kalau masih ada pemanggil lama. */\n      function copyLink(btn) {\n        var link = _linkOf(btn);\n        if (navigator.clipboard && navigator.clipboard.writeText) {\n          navigator.clipboard.writeText(link).then(function(){ _flash(btn); }).catch(function(){ _fallbackCopy(link, btn); });\n        } else { _fallbackCopy(link, btn); }\n      }\n      function openAs(btn) {\n        // Bawa token approver sbg ?back= → tampilan mekanik punya tombol kembali\n        var u = _linkOf(btn);\n        if (PAGE_TOKEN) u += '&back=' + encodeURIComponent(PAGE_TOKEN);\n        window.top.location.href = u;\n      }\n      function filterMechanics(query) {\n        var q = query.toLowerCase().trim();\n        var cards = document.querySelectorAll('#mechanicGrid .mon-card');\n        var visible = 0;\n        for (var i = 0; i < cards.length; i++) {\n          var show = !q || (cards[i].getAttribute('data-name') || '').indexOf(q) !== -1;\n          cards[i].style.display = show ? '' : 'none';\n          if (show) visible++;\n        }\n        document.getElementById('mechSearchEmpty').style.display = visible === 0 ? 'block' : 'none';\n      }\n    </script>\n\n    ";
